use anyhow::Context;
use bytes::BufMut;
use lz4_flex::frame::FrameEncoder;
use prost::encoding::{encode_key, encode_varint, encoded_len_varint, key_len, WireType};
use std::io::Write;

const STRING_TABLE_FIELD_TAG: u32 = 6;

pub struct CompressedProtobufSerializer {
    buffer: Vec<u8>,
    zipper: FrameEncoder<Vec<u8>>,
}

impl CompressedProtobufSerializer {
    pub fn encode(&mut self, item: impl prost::Message) -> anyhow::Result<()> {
        item.encode(&mut self.buffer)?;
        self.zipper.write_all(&self.buffer)?;
        self.buffer.clear();
        Ok(())
    }

    pub(crate) fn encode_string_table_entry(
        &mut self,
        value: impl AsRef<str>,
    ) -> anyhow::Result<()> {
        encode_str(STRING_TABLE_FIELD_TAG, value.as_ref(), &mut self.buffer)?;
        self.zipper.write_all(&self.buffer)?;
        self.buffer.clear();
        Ok(())
    }

    pub fn finish(self) -> anyhow::Result<Vec<u8>> {
        Ok(self.zipper.finish()?)
    }

    pub fn with_capacity(capacity: usize) -> Self {
        let buffer = Vec::with_capacity(capacity);
        let zipper = FrameEncoder::new(Vec::with_capacity(capacity));
        Self { buffer, zipper }
    }
}

/// Encodes a length-delimited string field into the given buffer, reserving
/// the exact number of bytes required to avoid intermediate re-allocations.
fn encode_str(tag: u32, value: &str, buffer: &mut Vec<u8>) -> anyhow::Result<()> {
    let byte_len = value.len();
    let encoded_len = key_len(tag) + encoded_len_varint(byte_len as u64) + byte_len;
    buffer
        .try_reserve(encoded_len)
        .context("profiling string table entry failed to allocate buffer capacity")?;
    encode_key(tag, WireType::LengthDelimited, buffer);
    encode_varint(byte_len as u64, buffer);
    buffer.put_slice(value.as_bytes());
    Ok(())
}

