impl InnerTelemetryShutdown {
    fn wait_for_shutdown(&self) {
        drop(
            self.condvar
                .wait_while(self.is_shutdown.lock().unwrap(), |is_shutdown| {
                    !*is_shutdown
                })
                .unwrap(),
        )
    }

    fn wait_for_shutdown_deadline(&self, deadline: std::time::Instant) {
        drop(
            self.condvar
                .wait_timeout_while(
                    self.is_shutdown.lock().unwrap(),
                    deadline.duration_since(std::time::Instant::now()),
                    |is_shutdown| !*is_shutdown,
                )
                .unwrap(),
        )
    }

    fn shutdown_finished(&self) {
        *self.is_shutdown.lock().unwrap() = true;
        self.condvar.notify_all();
    }
}
