            let batch = self.build_observability_batch();
            if !batch.is_empty() {
                let payload = data::Payload::MessageBatch(batch);
                match self.send_payload(&payload).await {
                    Ok(()) => self.payload_sent_success(&payload),
                    Err(err) => self.log_err(&err),
