            }
            self.deadlines
                .schedule_event(LifecycleAction::FlushData)
                .unwrap();
        }
        Lifecycle(Stop) => {
            if !self.data.started {
                return BREAK;
            }
            self.data.metric_buckets.flush_agregates();

            let batch = self.build_observability_batch();
            if !batch.is_empty() {
