        drop(
            self.condvar
                .wait_timeout_while(
                    self.is_shutdown.lock().unwrap(),
                    deadline.saturating_duration_since(std::time::Instant::now()),
                    |is_shutdown| !*is_shutdown,
                )
                .unwrap(),
        )
    }

    fn shutdown_finished(&self) {
        *self.is_shutdown.lock().unwrap() = true;
        self.condvar.notify_all();
    }
