/// Registers a new metric context and returns the associated `ContextKey`.
///
/// The metric will be named `name` and is associated to the provided `tags`.
/// `metric_type` and `namespace` describe how the metric should be aggregated
/// and reported, and `common` indicates whether the metric should be included
/// in the "common" metrics reported on every flush.
///
/// # Safety
///
/// * handle should be a non null pointer
/// * name should be a valid UTF-8 string
/// * tags should be a valid (possibly empty) `ddog_Vec_Tag`
pub unsafe extern "C" fn ddog_handle_register_metric_context(
    handle: &TelemetryWorkerHandle,
    name: ffi::CharSlice,
    tags: ffi::Vec<Tag>,
    metric_type: ddtelemetry::data::metrics::MetricType,
    common: bool,
    namespace: ddtelemetry::data::metrics::MetricNamespace,
) -> ContextKey {
    let name = name.to_utf8_lossy().into_owned();
    let tags = tags.into();
    handle.register_metric_context(name, tags, metric_type, common, namespace)
}

#[no_mangle]
/// Adds a data point to the metric context identified by `context`.
///
/// The point is aggregated locally and flushed to the intake on the next
/// metrics flush.
///
/// # Safety
///
/// * handle should be a non null pointer
/// * context should be a valid `ContextKey` returned by
///   `ddog_handle_register_metric_context`
pub unsafe extern "C" fn ddog_handle_add_point(
    handle: &TelemetryWorkerHandle,
    point: f64,
    context: &ContextKey,
) -> MaybeError {
    let extra_tags = Vec::new();
    crate::try_c!(handle.add_point(point, context, extra_tags));
    MaybeError::None
}

