pub unsafe extern "C" fn ddog_handle_add_point_with_tags(
    handle: &TelemetryWorkerHandle,
    point: f64,
    context: &ContextKey,
    extra_tags: ffi::Vec<Tag>,
) -> MaybeError {
    let extra_tags = extra_tags.into();
