int main(void) {
  // In this test we use the "metrics only" telemetry worker, which does not
  // send app lifecycle, dependency, or configuration events. Instead, it
  // only sends the metrics and logs that we submit from the current process.
  ddog_TelemetryWorkerBuilder *builder;
  ddog_MaybeError err = ddog_builder_instantiate(
      &builder, DDOG_CHARSLICE_C("service"), DDOG_CHARSLICE_C("c"),
      DDOG_CHARSLICE_C("1.0"), DDOG_CHARSLICE_C("1.0.0"));
  CHECK_ERROR(err);

  // Start the telemetry worker in metrics-only mode.
  ddog_TelemetryWorkerHandle *handle;
  err = ddog_builder_run_metric_logs(builder, &handle);
  CHECK_ERROR(err);

  // Register a metric context that all following points will be aggregated
  // into. `false` indicates this metric is not part of the "common" metrics.
  ddog_Vec_Tag tags = ddog_Vec_Tag_new();
  ddog_Vec_Tag_PushResult push_result = ddog_Vec_Tag_push(
      &tags, DDOG_CHARSLICE_C("service"), DDOG_CHARSLICE_C("telemetry-example"));
  if (push_result.tag != DDOG_VEC_TAG_PUSH_RESULT_OK) {
    fprintf(stderr, "could not push tag\n");
    exit(EXIT_FAILURE);
  }

  ddog_ContextKey context = ddog_handle_register_metric_context(
      handle, DDOG_CHARSLICE_C("test.metric"), tags, DDOG_METRIC_TYPE_COUNT,
      false, DDOG_METRIC_NAMESPACE_TRACERS);

  // Submit a few data points for the metric context.
  err = ddog_handle_add_point(handle, 1.0, &context);
  CHECK_ERROR(err);

  ddog_Vec_Tag extra_tags = ddog_Vec_Tag_new();
  err = ddog_handle_add_point_with_tags(
      handle, 2.0, &context, extra_tags);
  CHECK_ERROR(err);

  // Submit a log. It will be sent on the next flush, along with the metrics.
  err = ddog_handle_add_log(handle, DDOG_CHARSLICE_C("my-identifier"),
                            DDOG_CHARSLICE_C("Hello from metrics-only mode!"),
                            DDOG_LOG_LEVEL_DEBUG, DDOG_CHARSLICE_C(""));
  CHECK_ERROR(err);

  // Stop the worker, flushing the pending metrics and logs one last time,
  // then wait (with a timeout) for the shutdown to complete.
  err = ddog_handle_stop(handle);
  CHECK_ERROR(err);

  err = ddog_handle_wait_for_shutdown_ms(handle, 1000);
  CHECK_ERROR(err);

  ddog_handle_drop(handle);
  return EXIT_SUCCESS;
}

